  void Collections(int page){Base("collections");Studio.Header(root,"BUILD SOMETHING WORTH KEEPING","Business collections",data.Profile.Collection.Count+" / "+Pieces.All.Length+" contributing buildings discovered",Menu);for(int i=0;i<4;i++){int index=page*4+i;if(index>=CityCollections.All.Length)break;var set=CityCollections.All[index];float y=258+i*210;bool complete=CityCollections.Complete(data.Profile,set),claimed=data.Profile.Grants.Any(g=>g.Id=="collection-"+set.Id);var row=Studio.Box(root,"Collection "+set.Id,38,y,644,196);Studio.Label(row,set.Name,24,30,520,250,25,Studio.Text,heavy:true);for(int j=0;j<4;j++){string kind=set.Pieces[j];bool seen=data.Profile.Collection.Contains(kind);Studio.Image(row,kind,24+j*133,330,126,740,seen?Color.white:new Color(.28f,.38f,.46f));Studio.Label(row,seen?"✓":"?",24+j*133,1050,126,210,19,seen?Studio.Accent:Studio.Muted,TextAlignmentOptions.Center);}var button=Studio.Button(row,claimed?"CLAIMED":complete?"+200\nCOINS":set.Pieces.Count(data.Profile.Collection.Contains)+" / 4",560,420,144,720,()=>{if(CityCollections.Claim(data.Profile,set.Id)){sound.Cue("unlock");Save();Collections(page);}},complete&&!claimed);button.interactable=complete&&!claimed;}
