  void ComboDetails(int index){var combo=ComboBook.All[index];var m=Studio.Modal(root,combo.Name.ToUpperInvariant(),()=>Combos(index/4));Studio.Label(m,combo.Rule+"\n\nThis badge requires real flow. Placing an unrelated building nearby is not enough.",44,240,632,300,29,Studio.Text);Mission example=null;for(int i=0;i<104;i++){var mission=Campaign.Get(i);if(Campaign.Combos(mission.Solution,Resolver.Run(mission.Solution,mission.Multiplier)).Contains(combo.Name)){example=mission;break;}}if(example!=null){int level=example.Index;var used=CityCollections.Contributors(example.Solution,Resolver.Run(example.Solution,example.Multiplier));var types=example.Solution.Nodes.Where(n=>used.Contains(n.Id)).Select(n=>n.Kind).Distinct().Take(4).ToArray();for(int i=0;i<types.Length;i++)Studio.Image(m,types[i],38+i*168,570,150,230);Studio.Label(m,"Find it in city "+(level+1)+" · "+example.Title,44,840,632,120,27,Studio.Accent);var button=Studio.Button(m,data.Profile.CanSelect(level)?"TRY THIS CITY  →":"UNLOCK THIS CITY TO TRY IT",44,1090,632,135,()=>StartLevel(level),true);button.interactable=data.Profile.CanSelect(level);}Probe();}
