  void ProductDetails(string id){if(data.Profile.Cleared==0){message="Complete your first city to visit optional expansions.";Board();return;}var product=CommerceCatalog.Get(id);var m=Studio.Modal(root,product.Title,()=>Store(storePage));if(id=="cc.skin.neon"){string[] icons={"home","cafe","farm","warehouse","bank","factory","office","port"};for(int i=0;i<icons.Length;i++){var preview=Studio.Image(m,icons[i],38+i%4*168,215+i/4*135,150,135);preview.GetComponent<UnityEngine.UI.Image>().sprite=WorldArt.FindVariant("preview-neon-"+icons[i],"V5/neon",i,4,2);}}else Studio.Image(m,ProductArt(id),220,210,280,280);Studio.Label(m,product.Description+"\n\n"+(product.Consumable?"Consumables are saved on this device. Spent gems and tickets do not restore across devices. No account or cloud wallet is provided.":"Permanent purchase. Restore through the same Google Play account. No scoring advantage in the free campaign."),44,515,632,350,27,Studio.Text);bool owned=!product.Consumable&&data.Profile.Entitlements.Contains(id);if(owned){Studio.Label(m,"OWNED",44,900,632,70,34,Studio.Accent,TextAlignmentOptions.Center,true);if(id=="cc.skin.neon"||id=="cc.start.01")Studio.Button(m,"USE THIS FINISH",44,1080,632,135,()=>{data.Profile.SetFinish(id=="cc.skin.neon"?1:2);Save();Board();},true);else if(id.Contains("scenario"))Studio.Button(m,"EXPLORE THIS DISTRICT",44,1080,632,135,()=>Map(id.Contains("harbor")?6:7),true);else Studio.Button(m,"OPEN BLUEPRINTS",44,1080,632,135,Blueprints,true);}else if(!CommerceCatalog.Eligible(data.Profile,id)){Studio.Label(m,EligibilityText(id),44,925,632,220,26,Studio.Muted,TextAlignmentOptions.Center);}else if(store.ReadyFor(id)){Studio.Button(m,store.PriceFor(id),44,1080,632,135,()=>{store.Buy(id);StoreStatus();},true);}else{Studio.Label(m,store.Status+"\nCore play remains available offline.",44,900,632,285,25,Studio.Muted,TextAlignmentOptions.Center);}Probe();}
  string EligibilityText(string id)=>id=="cc.start.01"?"Available after exploring the first district or ten minutes and three successful cities.":id=="cc.blueprint.4"?"Save ideas in both free blueprint slots first.":id=="cc.skin.neon"?"Finish the first district to discover Neon City.":id=="cc.scenario.harbor"?"Explore 36 core cities first.":id=="cc.scenario.finance"?"Explore 60 core cities first.":id=="cc.reroll.5"?"Try Draft Practice first. Your first reroll there is free.":"Complete three cities to discover spark-gem decorations.";
